/*
** xfile_templates.h — the standard D3DRM template set for the .x format:
** the text Blitz3D's own loader_x.cpp registered via D3DRM_XTEMPLATES
** before opening a file. Template *definitions* like Mesh/Frame/Material
** are indeed never re-declared inside a Blitz3D-authored .x - only a
** modeller's own extension templates, like tiny.x's XSkinMeshHeader/
** SkinWeights/VertexDuplicationIndices, are. Header is the one exception:
** exporters commonly emit an explicit top-level `Header { major; minor;
** flags; }` *object* using this standard template (car.x, one of
** Blitz3D's own driver.bb sample assets, does) - it must be registered
** here like any other standard template or xfile_parse_object() fails on
** it and the whole load aborts with an empty mesh, no error surfaced.
**
** This is format data, not third-party source: the same public "x file
** templates" text every .x reader (Wine's d3dxof, DirectX's own SDK,
** every open .x parser) ships, reconstructed from the public spec - the
** same status as the Blitz3D command .htm docs this project already
** keeps for command signatures. No license header applies.
**
** Order matters: a template naming another template as a member's type
** (Mesh -> Vector, MeshFaceWraps -> Boolean2d, ...) can only reference
** one already registered - see xfile/VERSION's third contract point.
** This block is topologically sorted for that reason; do not reorder
** casually. Header has no dependencies and nothing depends on it, so it
** is registered first, ahead of Vector.
**
** Verified end-to-end (xfile_reserve_index_color + this block +
** xfile_parse_templates, then xfile_parse_object per top-level object)
** against a real 1.5MB production asset (assets/tiny.x - a skinned
** mesh: 4432 vertices, 6841 faces, 48 frames, 35 SkinWeights blocks) and
** against car.x (5 frames/meshes behind an explicit top-level Header).
*/
#ifndef XFILE_TEMPLATES_H
#define XFILE_TEMPLATES_H

/* xof header + 29 templates, in dependency order. Pass to
   xfile_parse_header()+xfile_parse_templates() on an XFileTemplates
   that has already had xfile_reserve_index_color() called on it. */
static const char kXFileStandardTemplates[] =
"xof 0302txt 0064\n"
"template Header\n"
"{\n"
"<3D82AB43-62DA-11CF-AB39-0020AF71E433>\n"
"WORD major;\n"
"WORD minor;\n"
"DWORD flags;\n"
"}\n"
"\n"
"template Vector\n"
"{\n"
"<3D82AB5E-62DA-11CF-AB39-0020AF71E433>\n"
"FLOAT x;\n"
"FLOAT y;\n"
"FLOAT z;\n"
"}\n"
"\n"
"template Coords2d\n"
"{\n"
"<F6F23F44-7686-11cf-8F52-0040333594A3>\n"
"FLOAT u;\n"
"FLOAT v;\n"
"}\n"
"\n"
"template Matrix4x4\n"
"{\n"
"<F6F23F45-7686-11cf-8F52-0040333594A3>\n"
"array FLOAT matrix[16];\n"
"}\n"
"\n"
"template ColorRGBA\n"
"{\n"
"<35FF44E0-6C7C-11cf-8F52-0040333594A3>\n"
"FLOAT red;\n"
"FLOAT green;\n"
"FLOAT blue;\n"
"FLOAT alpha;\n"
"}\n"
"\n"
"template ColorRGB\n"
"{\n"
"<D3E16E81-7835-11cf-8F52-0040333594A3>\n"
"FLOAT red;\n"
"FLOAT green;\n"
"FLOAT blue;\n"
"}\n"
"\n"
"template TextureFilename\n"
"{\n"
"<A42790E1-7810-11cf-8F52-0040333594A3>\n"
"STRING filename;\n"
"}\n"
"\n"
"template Material\n"
"{\n"
"<3D82AB4D-62DA-11CF-AB39-0020AF71E433>\n"
"ColorRGBA faceColor;\n"
"FLOAT power;\n"
"ColorRGB specularColor;\n"
"ColorRGB emissiveColor;\n"
"[...]\n"
"}\n"
"\n"
"template MeshFace\n"
"{\n"
"<3D82AB5F-62DA-11CF-AB39-0020AF71E433>\n"
"DWORD nFaceVertexIndices;\n"
"array DWORD faceVertexIndices[nFaceVertexIndices];\n"
"}\n"
"\n"
"template Boolean\n"
"{\n"
"<4885AE61-78E8-11cf-8F52-0040333594A3>\n"
"DWORD truefalse;\n"
"}\n"
"\n"
"template Boolean2d\n"
"{\n"
"<4885AE65-78E8-11cf-8F52-0040333594A3>\n"
"Boolean u;\n"
"Boolean v;\n"
"}\n"
"\n"
"template MeshFaceWraps\n"
"{\n"
"<4885AE63-78E8-11cf-8F52-0040333594A3>\n"
"DWORD nFaceWrapValues;\n"
"array Boolean2d faceWrapValues[nFaceWrapValues];\n"
"}\n"
"\n"
"template IndexedColor\n"
"{\n"
"<1630B821-7842-11cf-8F52-0040333594A3>\n"
"DWORD index;\n"
"ColorRGBA indexColor;\n"
"}\n"
"\n"
"template MeshVertexColors\n"
"{\n"
"<1630B820-7842-11cf-8F52-0040333594A3>\n"
"DWORD nVertexColors;\n"
"array IndexedColor vertexColors[nVertexColors];\n"
"}\n"
"\n"
"template MeshMaterialList\n"
"{\n"
"<F6F23F42-7686-11cf-8F52-0040333594A3>\n"
"DWORD nMaterials;\n"
"DWORD nFaceIndexes;\n"
"array DWORD faceIndexes[nFaceIndexes];\n"
"[Material]\n"
"}\n"
"\n"
"template MeshNormals\n"
"{\n"
"<F6F23F43-7686-11cf-8F52-0040333594A3>\n"
"DWORD nNormals;\n"
"array Vector normals[nNormals];\n"
"DWORD nFaceNormals;\n"
"array MeshFace faceNormals[nFaceNormals];\n"
"}\n"
"\n"
"template MeshTextureCoords\n"
"{\n"
"<F6F23F40-7686-11cf-8F52-0040333594A3>\n"
"DWORD nTextureCoords;\n"
"array Coords2d textureCoords[nTextureCoords];\n"
"}\n"
"\n"
"template Mesh\n"
"{\n"
"<3D82AB44-62DA-11CF-AB39-0020AF71E433>\n"
"DWORD nVertices;\n"
"array Vector vertices[nVertices];\n"
"DWORD nFaces;\n"
"array MeshFace faces[nFaces];\n"
"[...]\n"
"}\n"
"\n"
"template Frame\n"
"{\n"
"<3D82AB46-62DA-11CF-AB39-0020AF71E433>\n"
"[...]\n"
"}\n"
"\n"
"template FrameTransformMatrix\n"
"{\n"
"<F6F23F41-7686-11cf-8F52-0040333594A3>\n"
"Matrix4x4 frameMatrix;\n"
"}\n"
"\n"
"template FloatKeys\n"
"{\n"
"<10DD46A9-775B-11cf-8F52-0040333594A3>\n"
"DWORD nValues;\n"
"array FLOAT values[nValues];\n"
"}\n"
"\n"
"template TimedFloatKeys\n"
"{\n"
"<F406B180-7B3B-11cf-8F52-0040333594A3>\n"
"DWORD time;\n"
"FloatKeys tfkeys;\n"
"}\n"
"\n"
"template AnimationKey\n"
"{\n"
"<10DD46A8-775B-11cf-8F52-0040333594A3>\n"
"DWORD keyType;\n"
"DWORD nKeys;\n"
"array TimedFloatKeys keys[nKeys];\n"
"}\n"
"\n"
"template AnimationOptions\n"
"{\n"
"<E2BF56C0-840F-11cf-8F52-0040333594A3>\n"
"DWORD openclosed;\n"
"DWORD positionquality;\n"
"}\n"
"\n"
"template Animation\n"
"{\n"
"<3D82AB4F-62DA-11CF-AB39-0020AF71E433>\n"
"[...]\n"
"}\n"
"\n"
"template AnimationSet\n"
"{\n"
"<3D82AB50-62DA-11CF-AB39-0020AF71E433>\n"
"[Animation]\n"
"}\n"
"\n"
"template XSkinMeshHeader\n"
"{\n"
"<3CF169CE-FF7C-44ab-93C0-F78F62D172E2>\n"
"WORD nMaxSkinWeightsPerVertex;\n"
"WORD nMaxSkinWeightsPerFace;\n"
"WORD nBones;\n"
"}\n"
"\n"
"template SkinWeights\n"
"{\n"
"<6F0D123B-BAD2-4167-A0D0-80224F25FABB>\n"
"STRING transformNodeName;\n"
"DWORD nWeights;\n"
"array DWORD vertexIndices[nWeights];\n"
"array FLOAT weights[nWeights];\n"
"Matrix4x4 matrixOffset;\n"
"}\n"
"\n"
"template VertexDuplicationIndices\n"
"{\n"
"<B8D65549-D7C9-4995-89CF-53A9A8B031E3>\n"
"DWORD nIndices;\n"
"DWORD nOriginalVertices;\n"
"array DWORD indices[nIndices];\n"
"}\n"
"\n";

#endif
